extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	var player: CharacterBody3D = find_by_name(main, "Player") as CharacterBody3D
	if not check("player", player != null, "Nella scena serve un CharacterBody3D chiamato Player"):
		return
	var anim_tree: AnimationTree = player.get_node_or_null("AnimationTree") as AnimationTree
	if not check("tree", anim_tree != null, "Player deve avere un nodo figlio AnimationTree"):
		return
	check("active", anim_tree.active, "L'AnimationTree deve essere attivo (active = true)")

	await wait_physics_frames(10)

	var blend_idle = anim_tree.get("parameters/Ground/blend_position")
	check("idle", blend_idle != null and float(blend_idle) < 0.5, "Da fermo il parametro parameters/Ground/blend_position deve essere vicino a 0")

	Input.action_press("move_forward")
	await wait_physics_frames(10)
	var blend_walk = anim_tree.get("parameters/Ground/blend_position")
	Input.action_release("move_forward")
	await wait_physics_frames(2)

	check("walk", blend_walk != null and float(blend_walk) > 1.0, "Camminando il parametro parameters/Ground/blend_position deve essere maggiore di 1.0 (letto %.2f)" % [float(blend_walk) if blend_walk != null else -1.0])

